    (1792, 0, 76),
    (1792, 1, -298),
    (1792, 2, 79),
    (1792, 7, -207),
    (1792, 8, -260),
    (1792, 9, -5),
    (1886, 9, -256),
    (1915, 2, -256),
    (1943, 1, -256),
